import {
  ActivityFeed,
  ChartCard,
  KpiRow,
  PageHeader,
  type ActivityItem,
  type ChartCardProps,
  type ChartCardRange,
  type CostPoint,
  type KpiItem,
  type PageChromeAction,
} from '@gntik-ai/blocks';
import { chartFmt } from '@gntik-ai/charts';
import { Plus, UserPlus } from '@gntik-ai/icons';
import { Button, ClickableCard, Grid, GridItem, Page, Section, Stack, type BreadcrumbItem } from '@gntik-ai/ui';
import { ConsoleShell, type ConsoleShellProps } from '../shared/ConsoleShell';
import {
  homeActivity,
  homeBreadcrumbs,
  homeKpis,
  homeQuickActions,
  homeRequestRanges,
  homeRequestsByRange,
  type QuickAction,
  type RequestPoint,
} from './data';

/** Second-chart settings (everything but its data and ranges, which have their own props). */
export type HomeSecondaryChart<S extends object> = Omit<ChartCardProps<S>, 'dataByRange' | 'ranges'>;

/**
 * `P` is the row type of the first chart (default: the infrastructure-cost fixture), `S` the row
 * type of the second one (default: requests and errors per day).
 */
export interface HomeDashboardProps<P extends object = CostPoint, S extends object = RequestPoint> {
  title: string;
  description: string;
  breadcrumbs: BreadcrumbItem[];
  /** Header actions (the last one is the primary). */
  actions: PageChromeAction[];
  kpis: readonly KpiItem[];
  /**
   * First chart: any ChartCard props (title, description, ranges, dataByRange, index, categories,
   * colors, kind, valueFormatter…). Unset fields keep the infrastructure-cost fixture.
   */
  primaryChart: ChartCardProps<P>;
  /** Data of the second chart, per range key. */
  requestsByRange: Readonly<Record<string, readonly S[]>>;
  requestRanges: readonly ChartCardRange[];
  /** Second chart: title, description, index, categories, colors, kind… (merged over the requests defaults). */
  secondaryChart: HomeSecondaryChart<S>;
  activity: readonly ActivityItem[];
  quickActions: readonly QuickAction[];
  /** Called with the id of a quick action card (cards with `href` also navigate). */
  onQuickAction: (id: string) => void;
  onViewAllActivity: () => void;
  /** Console frame overrides (nav, user, workspaces, topbar). */
  shell: Omit<ConsoleShellProps, 'children'>;
}

const REQUESTS_CHART: HomeSecondaryChart<RequestPoint> = {
  title: 'Requests',
  description: 'Requests and errors per day',
  index: 'day',
  categories: ['Requests', 'Errors'],
  colors: ['primary', 'rose'],
  kind: 'line',
  stacked: false,
  valueFormatter: chartFmt.num,
};

/** Home dashboard: header, KPI row, two charts, recent activity and quick actions in the console shell. */
export default function HomeDashboardPage<P extends object = CostPoint, S extends object = RequestPoint>({
  title = 'Overview',
  description = 'How your workspace is doing across projects, traffic and spend.',
  breadcrumbs = homeBreadcrumbs,
  actions = [
    { label: 'Invite members', icon: UserPlus, variant: 'secondary' },
    { label: 'New project', icon: Plus, variant: 'primary' },
  ],
  kpis = homeKpis,
  primaryChart,
  requestsByRange = homeRequestsByRange as unknown as Readonly<Record<string, readonly S[]>>,
  requestRanges = homeRequestRanges,
  secondaryChart,
  activity = homeActivity,
  quickActions = homeQuickActions,
  onQuickAction,
  onViewAllActivity,
  shell,
}: Partial<HomeDashboardProps<P, S>>) {
  const secondary = { ...(REQUESTS_CHART as unknown as HomeSecondaryChart<S>), ...secondaryChart };
  return (
    <ConsoleShell currentHref="/overview" breadcrumbs={breadcrumbs} {...shell}>
      <Page
        width="wide"
        header={<PageHeader breadcrumbs={null} title={title} description={description} status="" meta={[]} tabs={null} actions={actions} />}
      >
        <Stack gap={6}>
          <KpiRow items={kpis} />
          <Grid cols={{ base: 1, lg: 2 }} gap={6}>
            <ChartCard<P> titleAs="h2" {...primaryChart} />
            <ChartCard<S> titleAs="h2" {...secondary} ranges={requestRanges} dataByRange={requestsByRange} />
          </Grid>
          <Grid cols={{ base: 1, lg: 3 }} gap={6} align="start">
            <GridItem span={{ base: 1, lg: 2 }}>
              <Section
                variant="card"
                padding="md"
                title="Recent activity"
                actions={
                  <Button variant="ghost" size="sm" onClick={onViewAllActivity}>
                    View all
                  </Button>
                }
              >
                <ActivityFeed items={activity} label="Activity, newest first" />
              </Section>
            </GridItem>
            <Section title="Quick actions" description="Common next steps.">
              <Stack gap={3}>
                {quickActions.map((qa) => {
                  const Icon = qa.icon;
                  return (
                    <ClickableCard
                      key={qa.id}
                      title={qa.title}
                      description={qa.description}
                      icon={<Icon aria-hidden />}
                      href={qa.href}
                      onClick={() => onQuickAction?.(qa.id)}
                    />
                  );
                })}
              </Stack>
            </Section>
          </Grid>
        </Stack>
      </Page>
    </ConsoleShell>
  );
}

import { KPI_ITEMS, PROJECT_ACTIVITY, type ActivityItem, type ChartCardRange, type KpiItem } from '@gntik-ai/blocks';
import { BookOpen, KeyRound, Rocket, UserPlus, type LucideIcon } from '@gntik-ai/icons';
import type { BreadcrumbItem } from '@gntik-ai/ui';

/** A shortcut card in the "Quick actions" grid. */
export interface QuickAction {
  id: string;
  title: string;
  description: string;
  icon: LucideIcon;
  href?: string;
}

export interface RequestPoint {
  day: string;
  Requests: number;
  Errors: number;
}

export const homeBreadcrumbs: BreadcrumbItem[] = [{ label: 'Overview' }];

export const homeKpis: KpiItem[] = KPI_ITEMS;

export const homeActivity: ActivityItem[] = PROJECT_ACTIVITY;

export const homeQuickActions: QuickAction[] = [
  { id: 'deploy', title: 'Deploy a service', description: 'Ship a new build from a branch or tag.', icon: Rocket },
  { id: 'invite', title: 'Invite members', description: 'Add teammates and pick their role.', icon: UserPlus },
  { id: 'api-key', title: 'Create an API key', description: 'Scoped keys for CI and integrations.', icon: KeyRound },
  { id: 'docs', title: 'Read the docs', description: 'Guides, API reference and examples.', icon: BookOpen, href: '#docs' },
];

const DAYS7 = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const DAYS30 = Array.from({ length: 30 }, (_, i) => `Day ${i + 1}`);

const requestSeries = (labels: string[], base: number, step: number): RequestPoint[] =>
  labels.map((day, i) => ({
    day,
    Requests: Math.round(base + step * i + ((i * 37) % 11) * 180),
    Errors: Math.round(40 + ((i * 13) % 7) * 9),
  }));

/** Requests and errors per day, per range. */
export const homeRequestsByRange: Record<string, RequestPoint[]> = {
  '7d': requestSeries(DAYS7, 31_000, 1_200),
  '30d': requestSeries(DAYS30, 28_000, 340),
};

export const homeRequestRanges: ChartCardRange[] = [
  { value: '7d', label: '7d', summary: { value: '271,480', delta: { value: '+12.4%', direction: 'up', sentiment: 'positive' } } },
  { value: '30d', label: '30d', summary: { value: '1.08M', delta: { value: '+6.0%', direction: 'up', sentiment: 'positive' } } },
];

import {
  AppSidebarFooter,
  AppSidebarHeader,
  AppSidebarNav,
  AppTopbar,
  type AppSidebarFooterProps,
  type AppSidebarHeaderProps,
  type AppTopbarProps,
} from '@gntik-ai/blocks';
import { SidebarLayout, type BreadcrumbItem, type NavGroup, type SidebarLayoutProps, type UserMenuUser, type Workspace } from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface ConsoleShellProps
  extends Pick<AppSidebarHeaderProps, 'currentWorkspaceId' | 'onWorkspaceChange' | 'onCreateWorkspace'>,
    Pick<AppSidebarFooterProps, 'usage' | 'helpHref' | 'helpLabel' | 'userMenuItems' | 'onSignOut'>,
    Pick<SidebarLayoutProps, 'sidebarLabel' | 'collapseMode'> {
  /** Page content (usually a <Page>). */
  children: ReactNode;
  /** Sidebar navigation; defaults to the AppSidebar sample groups. */
  nav?: NavGroup[];
  /** Href of the current page, marks the active nav item. */
  currentHref?: string;
  breadcrumbs?: BreadcrumbItem[] | null;
  workspaces?: Workspace[] | null;
  user?: UserMenuUser | null;
  /** Extra AppTopbar props (environment, notifications, theme control…). */
  topbar?: Omit<AppTopbarProps, 'breadcrumbs' | 'user'>;
  /** localStorage key for the collapsed sidebar; `undefined` disables persistence. */
  storageKey?: string;
}

/**
 * The console frame shared by the templates: SidebarLayout with the AppSidebar header, nav and
 * footer, and the AppTopbar (breadcrumb, ⌘K search, notifications, theme, user menu).
 * Templates fill it with a Page; products swap the nav, workspaces, user, usage meter, help
 * link and user-menu items.
 */
export function ConsoleShell({
  children,
  nav,
  currentHref,
  breadcrumbs,
  workspaces,
  currentWorkspaceId,
  onWorkspaceChange,
  onCreateWorkspace,
  user,
  usage,
  helpHref,
  helpLabel,
  userMenuItems,
  onSignOut,
  topbar,
  storageKey,
  sidebarLabel,
  collapseMode,
}: ConsoleShellProps) {
  return (
    <SidebarLayout
      fullScreen
      storageKey={storageKey}
      sidebarLabel={sidebarLabel}
      collapseMode={collapseMode}
      sidebarHeader={({ collapsed }) => (
        <AppSidebarHeader
          collapsed={collapsed}
          workspaces={workspaces}
          currentWorkspaceId={currentWorkspaceId}
          onWorkspaceChange={onWorkspaceChange}
          onCreateWorkspace={onCreateWorkspace}
        />
      )}
      sidebar={({ collapsed }) => <AppSidebarNav groups={nav} currentHref={currentHref} collapsed={collapsed} />}
      sidebarFooter={({ collapsed }) => (
        <AppSidebarFooter
          collapsed={collapsed}
          user={user}
          usage={usage}
          helpHref={helpHref}
          helpLabel={helpLabel}
          userMenuItems={userMenuItems}
          onSignOut={onSignOut}
        />
      )}
      topbar={<AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />}
    >
      {children}
    </SidebarLayout>
  );
}
